根据研究结果调整任务实现结构，采用模块化设计：

1. 将核心逻辑拆分为两个模块：
   - core/tasks.js：纯函数操作（创建/更新/删除任务对象），不涉及文件IO
   - infra/tasksRepo.js：文件读写操作（loadTasks/saveTasks）

2. core/tasks.js实现（命名导出）：
```javascript
export function createTask(taskData) {
  const now = new Date().toISOString();
  return {
    id: Date.now().toString(),
    title: taskData.title?.trim() || '',
    description: taskData.description || '',
    priority: taskData.priority || 'medium',
    status: 'pending',
    createdAt: now,
    updatedAt: now
  };
}

export function updateTask(task, updates) {
  return { 
    ...task, 
    ...updates, 
    updatedAt: new Date().toISOString() 
  };
}

export function deleteTask(tasks, id) {
  return tasks.filter(task => task.id !== id);
}
```

3. infra/tasksRepo.js实现：
```javascript
import { promises as fs } from 'fs';

const filePath = './data/tasks.json';

export async function loadTasks() {
  try {
    const data = await fs.readFile(filePath, 'utf8');
    return JSON.parse(data);
  } catch (err) {
    if (err.code === 'ENOENT') return [];
    throw err;
  }
}

export async function saveTasks(tasks) {
  await fs.writeFile(filePath, JSON.stringify(tasks, null, 2));
}
```

4. 在server.js中组合使用：
```javascript
import * as taskCore from './core/tasks.js';
import * as taskRepo from './infra/tasksRepo.js';

// 创建任务示例
app.post('/tasks', async (req, res) => {
  const newTask = taskCore.createTask(req.body);
  const tasks = await taskRepo.loadTasks();
  tasks.push(newTask);
  await taskRepo.saveTasks(tasks);
  res.status(201).json(newTask);
});
```

